import { Group } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const root = new Group();

  // Store references for cleanup
  const primitiveHandles = [];
  let gltfScene = null;
  let riseInTimeline = null;

  // Load GLB mesh
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      gltfScene = gltf.scene || gltf;
      root.add(gltfScene);
    });
  }

  // Apply cinematic primitives
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    if (typeof ctx.primitives[prim.name] === 'function') {
      const handle = ctx.primitives[prim.name](root, prim.params);
      primitiveHandles.push(handle);
    }
  }

  // Interaction handlers
  const handlers = {};

  // Hover – rise-in preset (subtle, 0.15 units)
  riseInTimeline = gsap.fromTo(
    root.position,
    { y: 0.15 },
    {
      y: 0,
      duration: 0.7,
      ease: 'power3.out',
      paused: true,
    }
  );

  handlers.hover = () => {
    if (riseInTimeline) {
      riseInTimeline.restart();
    }
  };

  // Click – emit navigation event
  handlers.click = () => {
    ctx.emit('hub-features.select');
  };

  root.userData.handlers = handlers;

  // Cleanup routine
  root.userData.cleanup = () => {
    // Kill GSAP timeline
    if (riseInTimeline) {
      riseInTimeline.kill();
      riseInTimeline = null;
    }

    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
    }
    primitiveHandles.length = 0;

    // Dispose GLTF resources
    if (gltfScene) {
      gltfScene.traverse((node) => {
        if (node.isMesh) {
          if (node.geometry) {
            node.geometry.dispose();
          }
          const mat = node.material;
          if (Array.isArray(mat)) {
            mat.forEach((m) => {
              if (m.map) m.map.dispose();
              m.dispose();
            });
          } else if (mat) {
            if (mat.map) mat.map.dispose();
            mat.dispose();
          }
        }
      });
      root.remove(gltfScene);
      gltfScene = null;
    }
  };

  return root;
}
